INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('7b2a08f3-e738-4739-af32-543f1fe74f4c', '21feff02-016d-46e2-bb9d-c27495133b1b', '90. óra: Gyakorlóóra', 'Matematikai szövegezésű feladatok gyakorlása, ábrakészítés, összefüggések.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "3168a757-f1fc-48ed-ba0f-ab0dfa65ae67", "text": "Apa 4 évvel idősebb, mint Anya. Életkoruk összege 76 év. Hány éves Anya? (2x + 4 = 76 -> 2x = 72)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "36"}, {"id": "af21cb0f-d27d-4656-8684-6f70315af3b6", "text": "Hány éves Apa? (36 + 4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "40"}, {"id": "70afbcf6-35a5-4913-b11c-ca0c155dfa30", "text": "Egy téglalap kerülete 40 cm. Hosszabbik oldala 4 cm-rel hosszabb a rövidebbnél. Hány cm a rövidebb oldal? (2*(x + x+4) = 40 -> 4x + 8 = 40)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}, {"id": "64f4188a-7df2-4520-ada9-64f9b38cb253", "text": "Hány cm a hosszabbik oldal? (8 + 4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}, {"id": "6c63252f-262f-4278-a6a1-99e828514681", "text": "A szakaszos ábrázolás nagymértékben segít a szöveges feladatok összefüggéseinek megértésében.", "type": "true-false", "options": [{"id": "75ce4217-622b-4bfe-bc79-910c60d894da", "text": "Igaz", "isCorrect": true}, {"id": "26008aab-1f31-4448-ac8f-36b2efa2239a", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "92e3588c-a0ef-4180-afb6-1ed8813630b8", "text": "Három egymást követő egész szám összege 45. Mi a legkisebb szám? (x + x+1 + x+2 = 45 -> 3x + 3 = 45)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "14"}, {"id": "57362a81-cb40-4c8a-934c-fe71f89bbdd2", "text": "A válaszmondat felírása kötelező a szöveges feladat végén.", "type": "true-false", "options": [{"id": "a653b955-cd6e-48ac-b9c9-d06635897a09", "text": "Igaz", "isCorrect": true}, {"id": "d0e4705e-6aa0-43cb-98a2-11b2220b9c9d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('d9baaf2e-4c7c-4f60-8508-32b0f9a5acd9', '21feff02-016d-46e2-bb9d-c27495133b1b', '91. óra: Feladatmegoldás', 'Hétköznapi vásárlási, méréseket és egyenleteket tartalmazó szöveges feladatok.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "6e905b16-cae5-4a71-aaeb-90e14f16153e", "text": "3 füzet és 1 toll összesen 1100 Ft-ba kerül. A toll ára 200 Ft. Hány Ft 1 füzet ára? (3x + 200 = 1100 -> 3x = 900)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "300"}, {"id": "76068563-c736-4a9f-803d-d3531965c7f1", "text": "Peti 2000 Ft-tal ment a boltba. Vett 3 kg narancsot 500 Ft/kg áron. Hány Ft visszajárót kapott? (2000 - 1500)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "500"}, {"id": "93aca8f7-46f4-4ec6-b1f0-c87dd1f2f235", "text": "Egy raktárban 120 láda gyümölcs van. Az első nap elvitték a 1/3-át, a második nap a megmaradt ládák felét. Hány láda maradt? (120 - 40 = 80, 80 - 40)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "40"}, {"id": "a683c625-d662-45f8-8c0e-8ce84fad9325", "text": "A mindennapi életben sok probléma modellezhető egyenlettel.", "type": "true-false", "options": [{"id": "4941f349-2d10-4776-bbbd-a24911bc4279", "text": "Igaz", "isCorrect": true}, {"id": "58b61d6b-6d64-4a77-a81e-a28e8a14d046", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "6772d790-cbaa-4a37-a3ce-fac51f349a8a", "text": "Melyik egyenlet írja le: ''Egy szám 4-szeresénél 5-tel több a 25''? (4x + 5 = 25)", "type": "multiple-choice", "options": [{"id": "9423c9af-b16a-4000-b5e9-5a2397073ada", "text": "4x + 5 = 25", "isCorrect": true}, {"id": "aa607901-7b98-4462-b0b3-c05e951a8952", "text": "x + 4 + 5 = 25", "isCorrect": false}, {"id": "701a9cba-455f-4a1a-bcec-5d302bb77e52", "text": "4x - 5 = 25", "isCorrect": false}, {"id": "47ee8821-b835-4375-8dd2-9c453eafa626", "text": "x / 4 + 5 = 25", "isCorrect": false}], "timeLimit": 15}, {"id": "3973043b-99ff-4bad-9080-b81e4aee08c2", "text": "Mennyi a gondolt szám a 4x + 5 = 25 egyenletben?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "9d81aff7-1706-45ad-801a-670c5f6bd717", "text": "Az ellenőrzést a feladat eredeti szövegébe való behelyettesítéssel végezzük.", "type": "true-false", "options": [{"id": "1d81923a-9574-4f66-a1f8-0e3f31c5aae0", "text": "Igaz", "isCorrect": true}, {"id": "0fef8915-012e-47fe-a003-bddec80a91e2", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('e07c2200-1336-49dc-8561-835360f336c3', '21feff02-016d-46e2-bb9d-c27495133b1b', '92. óra: Több megoldás is lehet', 'Több megoldást megengedő szöveges feladatok és egyenlőtlenségek vizsgálata.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "e590f2dd-c087-46b4-8c83-94bdc21d5c82", "text": "Katinak legfeljebb 10 Ft-ja lehet, és páros számú forintja van. Hányféle lehetséges összege lehet természetes számokban? (0, 2, 4, 6, 8, 10)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "edc1028e-802b-496b-b5d4-091e20504b17", "text": "Mely kifejezés jelenti azt, hogy ''legfeljebb 5''?", "type": "multiple-choice", "options": [{"id": "22c0648a-bd12-4a79-9ba2-28a4c038b2e4", "text": "Kisebb vagy egyenlő, mint 5 (x <= 5)", "isCorrect": true}, {"id": "5d35a797-a4d1-45f5-b528-5e3756f9831d", "text": "Nagyobb, mint 5", "isCorrect": false}, {"id": "897845b7-de9b-4cb9-a9d4-0127c254a2f1", "text": "Pontosan 5", "isCorrect": false}, {"id": "b644b48e-ce7a-4a91-8f1e-80e4e02b4366", "text": "Legalább 5", "isCorrect": false}], "timeLimit": 15}, {"id": "d126ebc6-d6e2-4e10-be9c-737ce97c81af", "text": "Mely kifejezés jelenti azt, hogy ''legalább 5''?", "type": "multiple-choice", "options": [{"id": "f1e6e15f-ca25-4cf9-98a1-a31feb63278f", "text": "Nagyobb vagy egyenlő, mint 5 (x >= 5)", "isCorrect": true}, {"id": "4c0d4d3c-775f-4de5-82ee-28768d5f8c17", "text": "Kisebb, mint 5", "isCorrect": false}, {"id": "da32bdf4-add2-4301-a320-e9155f54d37f", "text": "Pontosan 5", "isCorrect": false}, {"id": "0ab2650e-1f30-4fd6-a4a7-a1a515571276", "text": "Legfeljebb 5", "isCorrect": false}], "timeLimit": 15}, {"id": "202d6515-0fe6-4d6a-88c0-5621abab1d8a", "text": "A ''legalább 3 és legfeljebb 6'' feltételnek eleget tevő egész számok száma: 3, 4, 5, 6 (összesen 4 szám).", "type": "true-false", "options": [{"id": "940b09ca-15a7-4956-9f7c-357c14d130e9", "text": "Igaz", "isCorrect": true}, {"id": "0b76b3f8-9c3c-4fed-9c52-afb36981b8b9", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "4d8dc132-e9bc-4cc8-8bd9-792e6af014a9", "text": "Hány természetes szám megoldása van a 2 * x <= 8 egyenlőtlenségnek? (x = 0, 1, 2, 3, 4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "99e5a1bb-d864-4fff-9702-37c980d89f96", "text": "A több megoldással rendelkező feladatoknál az összes megoldás megtalálása a cél.", "type": "true-false", "options": [{"id": "35ad73e9-7101-439f-a62d-820337610d60", "text": "Igaz", "isCorrect": true}, {"id": "0af34ac5-65d1-49c0-8edd-bfdcaff9d394", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "c47afec2-d5d7-4a72-81e0-2c629b54de08", "text": "Melyik legkisebb természetes szám teljesíti az x > 7 egyenlőtlenséget?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('70ba3d55-d5bf-43c7-af89-f9561b5fa014', '21feff02-016d-46e2-bb9d-c27495133b1b', '93. óra: Létraverseny II.', 'Versenyszerű feladatmegoldás páros munkában a százalék és szöveges feladatok témakörében.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "92114f0c-718b-4df1-baa8-0d151f912e0c", "text": "Mennyi 1000 Ft-nak a 15%-a?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "150"}, {"id": "0afd955a-764d-432f-b4a8-33002d35b176", "text": "Melyik szám teszi igazzá: 2 * x + 10 = 50?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "a0db48de-a999-481b-8aff-23b23a62c8ee", "text": "Ha 3 kg narancs 1200 Ft, mennyibe kerül 5 kg narancs?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2000"}, {"id": "df658a83-6269-439b-a92a-0dfce12355af", "text": "Hány százalék felel meg a 3/5 törtnek? (3/5 = 60/100)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}, {"id": "4fe9d942-22f7-4680-a2d0-b3fe77f067cb", "text": "Gondoltam egy számot, elosztottam 3-mal, hozzáadtam 4-et és 10-et kaptam. Mi a szám? ((10-4)*3)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "18"}, {"id": "6c64314e-00cb-492d-a316-3122ca16f3c1", "text": "A játékos feladványok erősítik az osztály közösségét és a matematikai önbizalmat.", "type": "true-false", "options": [{"id": "e23b6594-6bd4-44b2-83ea-63085a4ba4d2", "text": "Igaz", "isCorrect": true}, {"id": "d4a6f507-e3a8-412d-a1cd-bdf42f67d88d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "72b86f55-cf53-42ca-84ec-e4c17ebb52f7", "text": "Mennyi 400-nak a 25%-a?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('a9f395e0-8d3a-4a26-a906-ecde7601cb1f', '21feff02-016d-46e2-bb9d-c27495133b1b', '94. óra: Összefoglalás', 'A fejezet fogalmainak (arány, egyenes arányosság, százalék, nyitott mondatok) összefoglalása.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "b4d10537-189f-41ac-b4c9-e500d31bcccf", "text": "Mennyi a 8 : 24 arány egyszerűsített alakja?", "type": "multiple-choice", "options": [{"id": "7755111e-f04a-4d8e-be1b-e6ceb6fa70c2", "text": "1 : 3", "isCorrect": true}, {"id": "80f6b09e-e6df-40c7-bfa4-829bf341710e", "text": "1 : 4", "isCorrect": false}, {"id": "6b47a52d-2d4b-404b-bc45-eb988ab2023a", "text": "2 : 3", "isCorrect": false}, {"id": "c60234c3-2a24-40b3-bf5f-2410dd7f386f", "text": "3 : 1", "isCorrect": false}], "timeLimit": 15}, {"id": "c6065758-bc6a-4ae1-883d-5e35a1e19672", "text": "Hány százalék felel meg a 1/2-nek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "50"}, {"id": "03f71607-5397-454d-8010-c70c292e8502", "text": "Hány százalék felel meg a 1/5-nek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "5f87bbc9-b810-4915-b9bd-c377f7e9ebd4", "text": "Mennyi 600 Ft-nak a 30%-a?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "180"}, {"id": "df4620d6-88bd-4b23-94a3-7ab0077ac389", "text": "Melyik szám teszi igazzá: 4 * x - 8 = 32? (40/4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "2811d41f-eed0-4bee-b843-4370333c9c5e", "text": "Az egyenes arányosság grafikonja az origóból induló félegyenes.", "type": "true-false", "options": [{"id": "41daa63a-60ee-4404-882c-ecadb7d868c7", "text": "Igaz", "isCorrect": true}, {"id": "92a9d715-9c5a-4762-9d19-9186fa0eaa74", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "e2ae3984-1c23-4303-aafd-552c1d111417", "text": "Mennyi 150-nek a 4/5 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "120"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('2717f5c5-f93b-4caf-a538-e9a38598ae23', '21feff02-016d-46e2-bb9d-c27495133b1b', '95. óra: Gyakorlóóra', 'Gyakorló feladatok önállóan, becslés és ellenőrzés.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "a6accfb3-1e49-41ec-ba9a-39f4a60ab3b3", "text": "Egy 8000 Ft-os táska ára 25%-kal csökkent. Hány Ft a kedvezmény? (8000 * 0,25)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2000"}, {"id": "17d37980-2d74-4a4e-b630-b429bdb1f271", "text": "Mennyi a táska új ára? (8000 - 2000)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6000"}, {"id": "5752907f-ee94-43d6-9d05-5d6994f17ae3", "text": "Melyik szám teszi igazzá: (x + 4) : 5 = 6?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "26"}, {"id": "b210c0ab-3448-4935-a947-62c8653bdb69", "text": "Ha 4 kg alma 1600 Ft, egyenes arányosság esetén 7 kg alma 2800 Ft-ba kerül.", "type": "true-false", "options": [{"id": "9e2cf83a-cb0a-45ac-8656-5391fd540dc1", "text": "Igaz", "isCorrect": true}, {"id": "77c75a22-0cb0-46ce-aceb-c19d3091d65b", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "e3b50c71-2eb8-42ac-96b3-2b3c17ba1e88", "text": "Mennyi 50-nek a 120%-a? (50 * 1,2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}, {"id": "65f661b8-3e14-4635-a031-ee0ebb621692", "text": "Az ellenőrzés mindig megnyugtató visszajelzést ad a feladat helyességéről.", "type": "true-false", "options": [{"id": "c6be1818-cd97-4abc-8b9e-103e4558ccda", "text": "Igaz", "isCorrect": true}, {"id": "4d41a76f-45a5-4a5c-927c-65d859c18eb5", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "dc918e60-ffac-4bdd-b939-d0b19547aebf", "text": "Mennyi 1000-nek az 1%-a?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('a1923c3f-0f8b-4584-8fc7-69573e703ffa', '21feff02-016d-46e2-bb9d-c27495133b1b', '96. óra: Témazáró dolgozat', 'Témazáró számonkérés az Arány, százalék, szöveges feladatok témakörből (10 kérdés).', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "7849cdad-3168-4d1b-bfaf-7305109f5228", "text": "1. Mennyi a 10 : 35 arány egyszerűsített alakja?", "type": "multiple-choice", "options": [{"id": "c8b54614-b752-4010-90ac-cb0b436bd308", "text": "2 : 7", "isCorrect": true}, {"id": "fee72e1d-bc02-4f0a-b831-8f7541cdc8a3", "text": "1 : 35", "isCorrect": false}, {"id": "ccdf4ece-f36a-4367-8fbb-b91e943e89ef", "text": "2 : 5", "isCorrect": false}, {"id": "6ee2323d-112a-4718-bf46-a00a507254d2", "text": "5 : 7", "isCorrect": false}], "timeLimit": 15}, {"id": "5992760e-3943-40ba-b79d-1721ebb5a7f4", "text": "2. Ossz el 600 Ft-ot 1 : 2 arányban! Hány Ft a nagyobbik rész?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "400"}, {"id": "616a484a-aadd-4436-b0c5-bf529816971d", "text": "3. Ha 3 kg narancs 1500 Ft, mennyibe kerül 4 kg narancs?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2000"}, {"id": "2fb057a5-2ae8-4d82-bf91-4ec61746f910", "text": "4. Hány százalék felel meg a 3/4 törtszámnak?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "75"}, {"id": "d82557b2-15b1-406e-824f-f374cb983a05", "text": "5. Mennyi 4000 Ft-nak a 15%-a?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "600"}, {"id": "a3a953c6-2259-4702-a5e9-054bee838ce3", "text": "6. Melyik szám teszi igazzá: 3 * x + 8 = 35?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "9"}, {"id": "ce95b9f0-711f-4ab2-a226-4b18ec421ca0", "text": "7. Gondoltam egy számot, elosztottam 2-vel, kivontam belőle 5-öt, 10-et kaptam. Mi a szám?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "18bfb20c-6e1c-440a-90d9-b582912ad555", "text": "8. Mennyi 200-nak a 4/5 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "160"}, {"id": "463e3d5e-f784-4b14-a4d4-eaa524ffc36f", "text": "9. Az egyenes arányosság esetén a két mennyiség hányadosa állandó.", "type": "true-false", "options": [{"id": "d4a07247-150e-41a6-8998-c49a6fe84db2", "text": "Igaz", "isCorrect": true}, {"id": "9ac752ac-5551-4a75-839a-3e367e4bfcdb", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "e75e0437-1f15-4d41-aaae-db4e872c843f", "text": "10. Egy 5000 Ft-os nadrág ára 10%-kal nőtt. Mennyi az új ár? (Ft-ban)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5500"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('b3025758-51ff-45d1-b8fe-e1dd4b0d8be4', '21feff02-016d-46e2-bb9d-c27495133b1b', '97. óra: Témazáró dolgozat értékelése', 'A témazáró dolgozat feladatainak megbeszélése, hibajavítás és összegzés.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "454e521c-bca9-4ec7-baf1-32315e947f05", "text": "Mi volt a legfontosabb tapasztalat a százalékszámítási feladatoknál?", "type": "multiple-choice", "options": [{"id": "c9cebe78-f546-4653-81e3-557b91aac0d0", "text": "Az 1% kiszámítása vagy a törtalakkal való szorzás biztonságos számolást ad", "isCorrect": true}, {"id": "3c2300e4-53dc-4a13-901e-df1f4677c9b4", "text": "A százalékjel elhagyása", "isCorrect": false}, {"id": "d22374b6-69a4-4cea-9a6f-56f37b9b2042", "text": "Mindig 100-at kell válaszolni", "isCorrect": false}, {"id": "fb89bf0f-4abc-41ed-80d7-4e4360cea6a1", "text": "Nem kell kiszámolni", "isCorrect": false}], "timeLimit": 15}, {"id": "44c75c49-aec2-4cd4-85a9-eb97fe89b640", "text": "Az arányos osztásnál az arányszámok összege adja meg a részek számát.", "type": "true-false", "options": [{"id": "0ba47046-f2b7-4c8e-a917-8eca0c48d49f", "text": "Igaz", "isCorrect": true}, {"id": "25895a1d-5a4e-4ba0-9b1d-02e8395ba6a6", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "0be47014-407a-4258-88e5-a788cf533d36", "text": "Mennyi 2000 Ft-nak a 20%-a?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "400"}, {"id": "7e264d54-9c41-4d4e-b6c1-a5f2760079c6", "text": "Melyik szám teszi igazzá: 5 * x - 10 = 40?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "f7103dc4-8a73-442e-86d2-500ce7fce1a4", "text": "A hibák elemzése segít a sikeresbb jövőbeli teljesítményben.", "type": "true-false", "options": [{"id": "e81d244c-7369-49b3-ba28-a73e97db2149", "text": "Igaz", "isCorrect": true}, {"id": "d187b03b-a3a4-4df7-9982-929cd327973f", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "ae52e565-e372-4c7d-a58b-ce7f47342df6", "text": "Mennyi 80-nak a 3/4 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}, {"id": "f9fe73e7-cdf8-40dd-a9e1-05ce9436efa7", "text": "Hány százalék felel meg az 1/10-nek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('f219c748-4e30-43c2-bbad-b5d2a2cb5a72', '21feff02-016d-46e2-bb9d-c27495133b1b', '98. óra: Hosszúság, tömeg, idő', 'A hosszúság, tömeg és idő mérésének ismétlése, mértékegységek és átváltások.', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "80429e8c-3843-4b1e-b408-1888bfd23ddb", "text": "Hány milliméter 1 méter?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1000"}, {"id": "a22e5f0e-493c-4daa-92bd-1a7b7c263abc", "text": "Hány dekagramm (dkg) 1 kilogramm (kg)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}, {"id": "e9085c29-e92d-4537-824e-41b38cabb40a", "text": "Hány másodperc van 1 órában? (60 * 60)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3600"}, {"id": "819886c9-80a2-41bb-8c3f-5e87d665b12d", "text": "Mennyi 2,5 km méterben?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2500"}, {"id": "423e561a-c891-4443-913e-cf88a095b89e", "text": "Hány kilogramm 3,5 tonna?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3500"}, {"id": "390172b5-99d2-44e1-b6c4-f15e625cbc53", "text": "Az időváltás 60-as alapon működik a másodperc, perc és óra között.", "type": "true-false", "options": [{"id": "37e98c31-dcff-4bda-b2af-6a8e51fd6b4c", "text": "Igaz", "isCorrect": true}, {"id": "6b34c55c-7a76-461e-a592-a34e41f4696c", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "7d66f385-baec-4ac0-a7ed-05587092993e", "text": "Hány perc 2 óra 15 perc?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "135"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('3ad4df51-89ab-4905-a4e5-b7a9fd87bf89', '21feff02-016d-46e2-bb9d-c27495133b1b', '99. óra: Hosszúság, tömeg, idő II.', 'Összetett mértékegység-átváltási feladatok és gyakorlás.', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "c80bc84b-f572-4a2a-b864-2554772eac0d", "text": "Hány cm van 4,5 m-ben?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "450"}, {"id": "1d8f27e8-cea6-4a0d-84f7-386b4e28e98b", "text": "Hány gramm 0,75 kg?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "750"}, {"id": "90c2aa6f-0dc8-4b6c-aefd-a31ee4b5920a", "text": "Hány napból áll 4 hét?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "28"}, {"id": "0fbc9d4b-f7d0-46ba-b1e3-8d16fe186a38", "text": "A 1500 m megegyezik 1,5 km-rel.", "type": "true-false", "options": [{"id": "d90454ef-6a05-4f7c-898b-e7cd9ac38b0b", "text": "Igaz", "isCorrect": true}, {"id": "fddb8731-abcc-41f4-b437-bf803ceca528", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "9dd3dd8b-b870-404c-a277-1c3f7f2fa42c", "text": "Mennyi 500 dkg kg-ban?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "4fbd3785-3cbd-4f51-8732-b7269523ce47", "text": "Hány perc 1 nap negyede (6 óra)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "360"}, {"id": "43556109-4721-46af-9e18-50e254b012b0", "text": "A nagyobb mértékegységből kisebb felé haladva szorzunk a váltószámmal.", "type": "true-false", "options": [{"id": "d2d517dd-8b2f-4422-88e1-d89f4cb525ae", "text": "Igaz", "isCorrect": true}, {"id": "6696ae71-0868-4ec1-b1ff-4e0060ba61c0", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());